    ["local coeffData = {\n    [2] = {\n        [2] = {  -- 2非凡\n            baseprice  = 150000\n        },\n        [1] = {  -- 1非凡+1普通\n            baseprice  = 70000\n        },\n        [0] = {  -- 2普通\n            baseprice  = 50000\n        }\n    },\n    [1] = {\n        [1] = {  -- 1非凡\n            baseprice  = 30000\n        },\n        [0] = {  -- 1普通\n            baseprice  = 10000\n        }\n    }\n}\n\nlocal data = coeffData[$2] and coeffData[$2][$3]\n\nlocal minCoeff, maxCoeff, baseprice\nif not data  then\n    baseprice = 10000\nelse\n    baseprice = data.baseprice\nend\nreturn Round(baseprice)"] = "local coeffData = {\n    [2] = {\n        [2] = {  -- 2 Потусторонний \n            baseprice  = 150000\n        },\n        [1] = {  -- 1 Потусторонний + 1 Common \n            baseprice  = 70000\n        },\n        [0] = {  -- 2 Common \n            baseprice  = 50000\n        }\n    },\n    [1] = {\n        [1] = {  -- 1 Потусторонний \n            baseprice  = 30000\n        },\n        [0] = {  -- 1 Common \n            baseprice  = 10000\n        }\n    }\n}\n\nlocal data = coeffData[$2] and coeffData[$2][$3]\n\nlocal minCoeff, maxCoeff, baseprice\nif not data  then\n    baseprice = 10000\nelse\n    baseprice = data.baseprice\nend\nreturn Round(baseprice)",
